    private void syncControlSelection(){if(api.bots().isEmpty())return;controlSelected.removeIf(name->{for(HeadlessBridgeClient.Bot b:api.bots())if(b.name.equalsIgnoreCase(name))return false;return true;});}
    private boolean allControlSelected(){if(api.bots().isEmpty()||controlSelected.size()!=api.bots().size())return false;for(HeadlessBridgeClient.Bot b:api.bots())if(!controlSelected.contains(b.name))return false;return true;}
    private void selectAllControls(){controlSelected.clear();for(HeadlessBridgeClient.Bot b:api.bots())controlSelected.add(b.name);}
    private void toggleControlBot(String name){if(controlSelected.contains(name))controlSelected.remove(name);else controlSelected.add(name);}
    private void goSelected(String action,String value){
        int sent=0;
        for(HeadlessBridgeClient.Bot bot:api.bots())if(controlSelected.contains(bot.name)&&bot.online()){
            String commandValue=value;
            if(action.equals("follow")){
                String[] parts=value.split("\\|",-1);String leader=parts.length>0?parts[0]:value;String distanceMode=parts.length>1?parts[1]:"auto";String jump=parts.length>2?parts[2]:"false";String sprint="false";
                float distance;
                if(distanceMode.equalsIgnoreCase("auto"))distance=1.8f;
                else{try{distance=MathHelper.clamp(Float.parseFloat(distanceMode.replace(',','.')),0.1f,16f);}catch(Exception e){distance=1.8f;}}
                int formationIndex=sent+1;
                commandValue=leader+"|"+String.format(Locale.ROOT,"%.2f",distance)+"|"+jump+"|"+sprint+"|"+leader+"|"+formationIndex;
            }
            api.command(action,bot.name,commandValue);sent++;
        }
        if(sent==0)api.setActionMessage("Ошибка: среди выбранных ботов нет подключённых к игре");
        else if(sent<controlSelected.size())api.setActionMessage("Команда отправлена online-ботам: "+sent+" из "+controlSelected.size());
        else api.setActionMessage("Команда отправлена выбранным ботам: "+sent);
    }
