        Fonts.sfuy.drawText(s,"Выбрано ботов: "+controlSelected.size(),mx0+18,my0+239,rgba(135,135,150,220),5.8f);
        button(s,mx,my,mx0+18,my0+266,118,28,"Отмена");button(s,mx,my,mx0+146,my0+266,mw-164,28,"Применить");
