    private boolean followSettingsClick(double mx,double my){
        float mw=410,mh=320,mx0=x+(w-mw)/2,my0=y+(h-mh)/2;followNickFocus=followDistanceFocus=false;
        if(in(mx,my,mx0+mw-31,my0+8,24,24)||in(mx,my,mx0+18,my0+266,118,28)){followModal=false;return true;}
        if(in(mx,my,mx0+18,my0+62,112,23)){followMode=0;return true;}if(in(mx,my,mx0+139,my0+62,112,23)){followMode=1;return true;}if(in(mx,my,mx0+260,my0+62,112,23)){followMode=2;followNickFocus=true;return true;}
        if(followMode==2&&in(mx,my,mx0+104,my0+94,mw-122,24)){followNickFocus=true;return true;}
        if(followMode!=1&&in(mx,my,mx0+104,my0+132,92,23)){followDistanceMode=0;return true;}if(followMode!=1&&in(mx,my,mx0+204,my0+132,92,23)){followDistanceMode=1;followDistanceFocus=true;return true;}
        if(followMode!=1&&followDistanceMode==1&&in(mx,my,mx0+304,my0+132,68,23)){followDistanceFocus=true;return true;}
        if(followMode!=1&&in(mx,my,mx0+104,my0+188,112,23)){followJump=!followJump;SAVED_FOLLOW_JUMP=followJump;return true;}
        
        if(in(mx,my,mx0+146,my0+266,mw-164,28)){applyFollowSettings();return true;}return true;
    }
    private void applyFollowSettings(){
        if(controlSelected.isEmpty()){api.setActionMessage("Ошибка: сначала выбери хотя бы одного бота");return;}
        if(followMode==1){goSelected("nothing","");followModal=false;return;}
        String target=followMode==0?localPlayerName():followPlayer.trim();
        if(target.isEmpty()||!target.matches("[A-Za-z0-9_]{1,16}")){api.setActionMessage("Ошибка: укажи корректный ник игрока");return;}
        String distanceValue="auto";
        if(followDistanceMode==1){try{float parsed=MathHelper.clamp(Float.parseFloat(followDistance.replace(',','.')),0.1f,16f);distanceValue=String.format(Locale.ROOT,"%.2f",parsed);followDistance=distanceValue;}catch(Exception e){api.setActionMessage("Ошибка: расстояние от 0.1 до 16");return;}}
        goSelected("follow",target+"|"+distanceValue+"|"+followJump+"|false");followModal=false;followNickFocus=followDistanceFocus=false;
    }
    private String localPlayerName(){try{return minecraft!=null&&minecraft.player!=null?minecraft.player.getName().getString():"";}catch(Exception e){return"";}}
