    private int minecraftConsoleColor(String value){if(value.contains("[mc_color=black]"))return rgba(35,35,35,255);if(value.contains("[mc_color=dark_blue]"))return rgba(0,0,170,255);if(value.contains("[mc_color=dark_green]"))return rgba(0,170,0,255);if(value.contains("[mc_color=dark_aqua]"))return rgba(0,170,170,255);if(value.contains("[mc_color=dark_red]"))return rgba(170,0,0,255);if(value.contains("[mc_color=dark_purple]"))return rgba(170,0,170,255);if(value.contains("[mc_color=gold]"))return rgba(255,170,0,255);if(value.contains("[mc_color=gray]"))return rgba(170,170,170,255);if(value.contains("[mc_color=dark_gray]"))return rgba(85,85,85,255);if(value.contains("[mc_color=blue]"))return rgba(85,85,255,255);if(value.contains("[mc_color=green]"))return rgba(85,255,85,255);if(value.contains("[mc_color=aqua]"))return rgba(85,255,255,255);if(value.contains("[mc_color=red]"))return rgba(255,85,85,255);if(value.contains("[mc_color=light_purple]"))return rgba(255,85,255,255);if(value.contains("[mc_color=yellow]"))return rgba(255,255,85,255);if(value.contains("[mc_color=white]"))return rgba(255,255,255,255);return 0;}
    private String consoleText(String line){return String.valueOf(line).replaceAll("\\s*\\[MC_COLOR=[A-Za-z_]+\\]\\s*"," ").trim();}
    private int consoleColor(String line){String value=String.valueOf(line).toLowerCase(Locale.ROOT);if(value.contains("[error]")||value.contains("ошибка")||value.contains("server_full")||value.contains("kicked")||value.contains("кик:")||value.contains("disconnect"))return rgba(239,84,91,255);if(value.contains("[warn]")||value.contains("warning")||value.contains("предупреж")||value.contains("reconnect")||value.contains("повторное подключение")||value.contains("socketclosed"))return rgba(246,183,72,255);int minecraftColor=minecraftConsoleColor(value);if(minecraftColor!=0)return minecraftColor;if(value.contains("[chat out]"))return rgba(80,226,178,255);if(value.contains("[chat]"))return rgba(105,220,255,255);if(value.contains("[server]"))return rgba(255,177,92,255);if(value.contains("[control]")||value.contains("команда отправлена")||value.contains("добавлен бот")||value.contains("изменён бот")||value.contains("удалён бот"))return rgba(184,130,255,255);if(value.contains("follow")||value.contains("goto")||value.contains("moving")||value.contains("перемещ")||value.contains("pathfinder"))return rgba(94,196,255,255);if(value.contains("подключен")||value.contains("подключён")||value.contains("в мире")||value.contains("online")||value.contains("spawn")||value.contains("успеш")||value.contains("сохранено"))return rgba(83,214,139,255);if(value.contains("[info]"))return rgba(145,190,255,235);return rgba(205,205,216,235);}
