    private int profileCountValue(){try{return Math.max(1,Math.min(50,Integer.parseInt(profileCount.isEmpty()?"1":profileCount)));}catch(Exception e){return 1;}}
    private void ensureProfiles(){int count=profileCountValue();if(count==1&&addMode==0)addMode=1;while(addNicks.size()<count)addNicks.add(addMode==2?randomNick():"");while(addNicks.size()>count)addNicks.remove(addNicks.size()-1);addOffset=Math.max(0,Math.min(addOffset,Math.max(0,count-7)));if(addMode==0)applyNormal();}
    private void setAddMode(int mode){addMode=profileCountValue()==1&&mode==0?1:mode;ensureProfiles();if(addMode==2)for(int i=0;i<addNicks.size();i++)addNicks.set(i,randomNick());else if(addMode==0){if(addNicks.get(0).trim().isEmpty())addNicks.set(0,"Bot");applyNormal();}addNickFocus=addMode==1?0:addMode==0?0:-1;}
    private void applyNormal(){if(addNicks.isEmpty())return;String base=addNicks.get(0).trim();for(int i=0;i<addNicks.size();i++)addNicks.set(i,i==0?base:base.isEmpty()?"":trimNick(base,i));}
    private String trimNick(String base,int number){String suffix=String.valueOf(number);int max=Math.max(1,16-suffix.length());return (base.length()>max?base.substring(0,max):base)+suffix;}
    private String randomNick(){String[] p={"Bot","Player","Noob","Pro","Cool","xD","Legend","Mini","Ultra","Super"};String[] q={"_XD","_Pro","_123","_MC","_BW","_OP","_YT","MC","PVP","HD"};return p[nickRandom.nextInt(p.length)]+(100+nickRandom.nextInt(900))+q[nickRandom.nextInt(q.length)];}
