    private long parseSeconds(int mode,String value){if(mode==0)return 0;try{return Math.max(0,Math.min(600000,Math.round(Double.parseDouble(value.replace(',','.'))*1000)));}catch(Exception e){api.setActionMessage("Ошибка: интервал входа 0–600 секунд");return-1;}}
    private long parseMillis(int mode,String value){if(mode==0)return 0;try{return Math.max(10,Math.min(1000,Math.round(Double.parseDouble(value.replace(',','.'))*1000)));}catch(Exception e){api.setActionMessage("Ошибка: частота слежения 0.01–1.00 сек");return-1;}}
    private boolean startBots(){ensureProfiles();String address=HeadlessServerStore.normalizeAddress(addServerMode==0?readyAddress(addReadyServer):serverAddress.trim());if(address==null)return false;long interval=parseSeconds(addConnectMode,addConnectDelay),refresh=parseMillis(addTrackingMode,addTrackingRefresh),launchInterval=addConnectMode==0?2500:interval;if(interval<0||refresh<0)return false;Set<String> unique=new HashSet<>();for(String raw:addNicks){String n=raw.trim();if(!n.matches("[A-Za-z0-9_]{3,16}")||!unique.add(n.toLowerCase(Locale.ROOT)))return false;}boolean first=true;int index=0;for(String raw:addNicks){String n=raw.trim();if(api.connected()){api.addLocalBot(n,address);api.command("addbot",address,n+"\n"+interval+"\n"+refresh);}else{if(!launcher.start(n,address,index*launchInterval,refresh)&&first)return false;api.addLocalBot(n,address);}if(first)selected=n;first=false;index++;}tab=1;SAVED_TAB=1;return true;}
    private void go(String a,String t,String v){api.command(a,t,v);} private void send(){String value=input.trim();if(value.isEmpty())return;ensureConsoleBot();if(consoleChatMode&&selected.isEmpty())return;consoleScroll=consoleAnimScroll=0;api.command(consoleChatMode?"say":"console",selected,value);input="";inputFocus=true;}
    @Override public boolean mouseScrolled(double mx,double my,double d){if(serverAddModal||followModal)return true;if(addModal){ensureProfiles();addOffset=Math.max(0,Math.min(Math.max(0,addNicks.size()-6),addOffset+(d<0?1:-1)));return true;}if(tab==5&&d!=0){List<String> lines=currentConsoleLines();float top=y+60+57,bottom=y+60+(h-72)-38,lineH=14;int visible=Math.max(1,(int)((bottom-top)/lineH));float max=Math.max(0,(lines.size()-visible)*lineH);consoleScroll=MathHelper.clamp(consoleScroll+(d>0?lineH*3:-lineH*3),0,max);return true;}if(tab==1&&d!=0){int rows=(int)Math.ceil(api.bots().size()/2f),visibleRows=Math.max(1,(int)(((h-72)-40)/106f));float min=-Math.max(0,rows-visibleRows)*106f;scroll=MathHelper.clamp(scroll+(d>0?106f:-106f),min,0);return true;}return super.mouseScrolled(mx,my,d);}
    @Override public boolean keyPressed(int key,int scan,int mod){if(key==GLFW.GLFW_KEY_ESCAPE){if(serverAddModal){serverAddModal=false;serverNameFocus=serverAddressFocus=false;return true;}if(followModal){followModal=false;followNickFocus=followDistanceFocus=false;return true;}if(changeModal){changeModal=false;changeNickFocus=changeServerFocus=false;return true;}if(addModal){addModal=false;countFocus=serverFocus=false;addNickFocus=-1;return true;}closeBack();return true;}if(serverAddModal){if(key==GLFW.GLFW_KEY_BACKSPACE){if(serverNameFocus&&!newServerName.isEmpty())newServerName=newServerName.substring(0,newServerName.length()-1);if(serverAddressFocus&&!newServerAddress.isEmpty())newServerAddress=newServerAddress.substring(0,newServerAddress.length()-1);return true;}if(key==GLFW.GLFW_KEY_ENTER){saveNewServer();return true;}return super.keyPressed(key,scan,mod);}if(followModal){if(key==GLFW.GLFW_KEY_BACKSPACE){if(followNickFocus&&!followPlayer.isEmpty())followPlayer=followPlayer.substring(0,followPlayer.length()-1);if(followDistanceFocus&&!followDistance.isEmpty())followDistance=followDistance.substring(0,followDistance.length()-1);return followNickFocus||followDistanceFocus;}if(key==GLFW.GLFW_KEY_ENTER){applyFollowSettings();return true;}return super.keyPressed(key,scan,mod);}if(key==GLFW.GLFW_KEY_BACKSPACE){if(inputFocus&&!input.isEmpty())input=input.substring(0,input.length()-1);if(countFocus&&!profileCount.isEmpty()){profileCount=profileCount.substring(0,profileCount.length()-1);ensureProfiles();}if(serverFocus&&!serverAddress.isEmpty())serverAddress=serverAddress.substring(0,serverAddress.length()-1);if(addConnectFocus&&!addConnectDelay.isEmpty())addConnectDelay=addConnectDelay.substring(0,addConnectDelay.length()-1);if(changeConnectFocus&&!changeConnectDelay.isEmpty())changeConnectDelay=changeConnectDelay.substring(0,changeConnectDelay.length()-1);if(addTrackingFocus&&!addTrackingRefresh.isEmpty())addTrackingRefresh=addTrackingRefresh.substring(0,addTrackingRefresh.length()-1);if(changeTrackingFocus&&!changeTrackingRefresh.isEmpty())changeTrackingRefresh=changeTrackingRefresh.substring(0,changeTrackingRefresh.length()-1);if(addNickFocus>=0&&addNickFocus<addNicks.size()&&!addNicks.get(addNickFocus).isEmpty()){String v=addNicks.get(addNickFocus);addNicks.set(addNickFocus,v.substring(0,v.length()-1));if(addMode==0)applyNormal();}if(changeNickFocus&&!changeNick.isEmpty())changeNick=changeNick.substring(0,changeNick.length()-1);if(changeServerFocus&&!changeServer.isEmpty())changeServer=changeServer.substring(0,changeServer.length()-1);return inputFocus||countFocus||serverFocus||addConnectFocus||changeConnectFocus||addTrackingFocus||changeTrackingFocus||addNickFocus>=0||changeNickFocus||changeServerFocus;}if(key==GLFW.GLFW_KEY_ENTER){if(changeModal){applyChange();return true;}if(addModal){if(startBots())addModal=false;return true;}if(inputFocus){send();return true;}}return super.keyPressed(key,scan,mod);}
    @Override public boolean charTyped(char c,int mod){if(Character.isISOControl(c))return false;if(serverAddModal){if(serverNameFocus&&newServerName.length()<32){newServerName+=c;serverFormError="";return true;}if(serverAddressFocus&&newServerAddress.length()<253&&(Character.isLetterOrDigit(c)||c=='.'||c==':'||c=='-'||c=='_')){newServerAddress+=c;serverFormError="";return true;}return false;}if(followModal){if(followNickFocus&&followPlayer.length()<16&&(Character.isLetterOrDigit(c)||c=='_')){followPlayer+=c;return true;}if(followDistanceFocus&&followDistance.length()<6&&(Character.isDigit(c)||c=='.'||c==',')){followDistance+=c;return true;}return false;}if(inputFocus&&input.length()<220){input+=c;return true;}if(countFocus&&Character.isDigit(c)&&profileCount.length()<2){profileCount+=c;ensureProfiles();return true;}if(addConnectFocus&&addConnectDelay.length()<7&&(Character.isDigit(c)||c=='.'||c==',')){addConnectDelay+=c;return true;}if(changeConnectFocus&&changeConnectDelay.length()<7&&(Character.isDigit(c)||c=='.'||c==',')){changeConnectDelay+=c;return true;}if(addTrackingFocus&&addTrackingRefresh.length()<7&&(Character.isDigit(c)||c=='.'||c==',')){addTrackingRefresh+=c;return true;}if(changeTrackingFocus&&changeTrackingRefresh.length()<7&&(Character.isDigit(c)||c=='.'||c==',')){changeTrackingRefresh+=c;return true;}if(serverFocus&&serverAddress.length()<253&&(Character.isLetterOrDigit(c)||c=='.'||c==':'||c=='-'||c=='_')){serverAddress+=c;return true;}if(addNickFocus>=0&&addNickFocus<addNicks.size()&&addNicks.get(addNickFocus).length()<16&&(Character.isLetterOrDigit(c)||c=='_')){addNicks.set(addNickFocus,addNicks.get(addNickFocus)+c);if(addMode==0)applyNormal();return true;}if(changeNickFocus&&changeNick.length()<16&&(Character.isLetterOrDigit(c)||c=='_')){changeNick+=c;return true;}if(changeServerFocus&&changeServer.length()<253&&(Character.isLetterOrDigit(c)||c=='.'||c==':'||c=='-'||c=='_')){changeServer+=c;return true;}return super.charTyped(c,mod);}
    private String formatUptime(long ms){long sec=Math.max(0,ms/1000),min=sec/60,hour=min/60;return hour+"ч "+(min%60)+"м "+(sec%60)+"с";}
    private void closeBack(){minecraft.displayGuiScreen(parent);if(module.isState())module.setState(false,true);}@Override public void onClose(){if(module.isState())module.setState(false,true);}@Override public boolean isPauseScreen(){return false;}
    private boolean in(double mx,double my,float x,float y,float w,float h){return mx>=x&&mx<=x+w&&my>=y&&my<=y+h;}private int rgba(int r,int g,int b,int a){return ColorUtils.rgba(r,g,b,a);}private String cut(String s,int n){if(s==null)return"—";s=s.replace('\n',' ').replace('\r',' ');return s.length()<=n?s:s.substring(0,Math.max(1,n-1))+"…";}
